        { "La colle de « {livro} » est honnête. La couverture, elle, promet des choses que l'intérieur n'est pas sûr de tenir.", situacao = "leitura" },
        { "{autor} a mis Dieu sait combien de temps à écrire ça. J'ai mis un après-midi à manger le coin de la page dix. Chacun son métier.", situacao = "leitura" },
        { "Ce livre a un goût {de_tema}. Ce n'est pas mauvais. Je m'attendais juste à un goût de colle.", situacao = "leitura" },
