        { "Le mot « {palavra} » est revenu. On s'appelle par nos prénoms, maintenant.", situacao = "leitura" },
        { "Je préfère les livres d'occasion. Ils arrivent assaisonnés : café, doigts, pluie, et la tristesse de quelqu'un d'autre au coin de la page.", situacao = "leitura", fase = { "adulta", "ancia" } },
        { "J'ai encore « {anterior} » sur l'estomac. Celui-ci attendra la digestion.", situacao = "leitura" },
