        { "J'ai grandi. Je passe encore par la fente, mais maintenant j'entre de profil, avec style.", situacao = "crescimento", fase = "jovem" },
        { "Ma peau me serre de nouveau. Je grandis comme un mauvais chapitre : par à-coups.", situacao = "crescimento", quando = "muda" },
        { "Quand je serai grande, je mangerai un dictionnaire entier, en commençant par l'entrée « balai », par vengeance.", situacao = "crescimento", fase = "jovem", curta = "Mon plan : grandir et manger l'entrée « balai »." },
        { "Encore une mue. Chaque peau que je laisse derrière moi garde une opinion que je n'ai plus.", situacao = "crescimento", quando = "muda" },
        { "J'avais peur des vieilles mites. Maintenant, ce sont les jeunes qui ont peur de moi. Je ne sais pas si j'ai grandi ou juste tourné au vinaigre.", situacao = "crescimento", fase = "adulta", curta = "Les nymphes me craignent. Grandie ou aigrie ?" },
        { "Avant, je mangeais n'importe quel papier. Aujourd'hui, je vérifie la page de copyright de « {livro} » avant de mordre. L'âge rend exigeante.", situacao = "crescimento", fase = "adulta" },
        { "Mes antennes n'entendent plus le balai venir de loin. C'est sans doute comme ça qu'on devient sage : sans avoir le choix.", situacao = "crescimento", fase = "ancia", curta = "J'entends moins. On dit sagesse. C'est l'âge." },
        { "À mon âge, chaque livre en rappelle un autre. Celui-ci me rappelle « {anterior} », je ne sais pas trop pourquoi, et c'est presque un compliment.", situacao = "crescimento", fase = "ancia" },
