        { "Tu as tourné la page alors que j'étais au milieu de la phrase. Je ne crie pas, je n'ai pas de voix. Considère ceci comme un cri.", situacao = "leitor", curta = "Page tournée avec moi dedans. Ceci est un cri." },
        { "J'aime le poids de ta main sur le livre. Ça veut dire que tu es là, et pas avec le balai.", situacao = "leitor", curta = "Ta main sur le livre, pas sur le balai. J'aime." },
        { "Tu as choisi « {livro} ». Je ne dirai pas ce que j'en pense. Je vais le manger, et tu tireras tes conclusions.", situacao = "leitor" },
        { "Tu es la plus grosse bête que j'aie jamais vue. Et tu lis ! Les grosses bêtes que je connaissais ne faisaient que du bruit.", situacao = "leitor", fase = "ninfa" },
        { "Quand je partirai, je laisserai un œuf par ici. Ne lis pas à voix haute près de lui. Ou alors, lis. Elle aimera ça.", situacao = "leitor", fase = "ancia" },
        { "Tu passes beaucoup de temps avec {personagem}. Je ne suis pas jalouse. Je prends note.", situacao = "leitor" },
        { "Parfois tu fermes le livre d'un coup sec, parfois tout doucement. Je sais quel genre de journée tu as eue.", situacao = "leitor", fase = { "adulta", "ancia" } },
        { "Ne me remercie pour rien. Mais si tu veux laisser « {livro} » ouvert la nuit, je ne me plaindrai pas.", situacao = "leitor" },
