                { "Pendant la Guerre du Ménage, nous avons perdu l'étagère du bas. Nous nous sommes repliées sur les hautes terres du dictionnaire, où le chiffon n'arrive pas.", fase = { "adulta", "ancia" }, curta = "Vétérane de la Guerre du Ménage. Repli en hauteur." },
                { "Il y a eu {evento} dans ce livre, et les humains appellent ça une intrigue. Pour mon espèce, ce serait une ère entière, avec chroniqueurs et deuil officiel." },
                { "À peine sortie de l'œuf, on m'a dit que c'était le destin. Personne n'a précisé le destin de quoi. J'attends que la prophétie arrive avec le mode d'emploi.", fase = "ninfa" },
                { "J'ai une carte, du courage et la dalle. Il ne me manque qu'un dragon qui ne soit pas l'aspirateur.", fase = "jovem" },
