                { "Je suis sortie de l'œuf, et quelqu'un aurait dû sonner de la trompette. Seule la sonnette a sonné. C'était le livreur.", fase = "ninfa" },
                { "J'ai découvert que je vis dans un royaume de sept étagères et un tyran au balai. Je ne sais pas encore de quel côté je suis.", fase = "ninfa" },
                { "Première leçon de guerre : l'ennemi a deux jambes et un chiffon humide.", fase = "ninfa" },
                { "Je veux un titre : Dévoreuse de Marges, Dame de la Plinthe. Pour l'instant, je ne suis que « le truc, là, dans le coin ».", fase = "ninfa" },
