                { "Je m'entraîne chaque nuit : courir du dos du livre à la plinthe en trois secondes. Aujourd'hui, deux. Le chat, une.", fase = "jovem" },
                { "J'ai formé une compagnie : moi, une mite à moitié aveugle et un acarien qui suit le mouvement. Le seul mot qui rime avec acarien, c'est « rien ». Les bardes ont tranché.", fase = "jovem" },
                { "L'aspirateur rugit, n'a qu'une bouche et avale tout. Si ce n'est pas un dragon, je ne sais pas ce que c'est.", fase = "jovem", curta = "L'aspirateur rugit et avale tout. Dragon." },
                { "L'étagère du haut est interdite. On dit qu'y vit un vieux dictionnaire que personne n'a jamais ouvert. Je veux voir.", fase = "jovem" },
