                { "Tout royaume a son méchant. Le mien porte un tablier, se lève tôt et croit à l'ordre.", fase = "adulta", curta = "Mon méchant porte un tablier et croit à l'ordre." },
                { "J'ai fait alliance avec les araignées du plafond : elles s'occupent des moustiques, moi du silence. Traité ancien.", fase = "adulta" },
