                { "J'ai examiné « {livro} » : colle récente, une empreinte de café, aucune trace de lutte. Soit c'est un cadeau, soit un crime parfait.", fase = { "ninfa", "jovem" }, curta = "Empreinte de café sur la couverture. C'est noté." },
