                { "J'ai vu bien des ménages, et chaque ménage a un commanditaire. Ce n'est jamais celui qui tient le chiffon. Avec l'âge, on apprend à regarder qui donne l'ordre.", fase = "ancia" },
                { "J'ai regardé l'étagère encore une fois, lentement, comme si c'était {lente}. Tout est à sa place. C'est exactement ce qui m'inquiète.", fase = { "adulta", "ancia" } },
                { "Le mot « {palavra} » revient trop souvent sur la scène. Aucun mot ne revient autant par hasard." },
                { "Je n'accuse personne. J'observe juste qui a des mains." },
                { "Premier indice de ma vie : une miette sur le tapis. Je l'ai suivie jusqu'à la cuisine. Affaire résolue : quelqu'un mange en cachette.", fase = "ninfa" },
                { "Première leçon : dans cette maison, la plus petite est coupable jusqu'à preuve du contraire.", fase = "ninfa", curta = "Ici, la plus petite est coupable." },
                { "Mon premier rapport : la maison est grande, le chat est suspect, le balai est coupable.", fase = "ninfa" },
                { "La première chose que j'ai apprise, c'est de ne me fier à personne qui a des mains.", fase = "ninfa" },
                { "Si on demande, j'étais dans le dictionnaire toute la nuit. J'ai des témoins : les mots.", fase = "ninfa" },
                { "Suspect numéro un : le chat. Mobile : il me regarde. Preuve : il me regarde beaucoup.", fase = "ninfa" },
                { "J'ai passé la nuit à enquêter sur la disparition du pain. Conclusion : tu l'as mangé debout, devant le frigo. Je ne dirai rien.", fase = "jovem" },
                { "J'ai examiné la couverture de près. J'ai trouvé une empreinte, deux taches et mon propre reflet. Tous suspects.", fase = "jovem" },
                { "Un bouton disparaît, c'est la mite. Le rideau se déchire, c'est la mite. Je commence à me trouver très douée.", fase = "jovem" },
                { "Aujourd'hui, j'ai joué la virgule sur une page entière. Personne ne s'est douté de rien. Le texte était même plus clair.", fase = "jovem" },
                { "J'ai fouillé les archives mortes de la maison. Factures payées, lettres sans réponse, une photo déchirée. Quelqu'un ici a un secret.", fase = "jovem" },
                { "Lumière allumée au salon à deux heures du matin. Livre ouvert, tasse froide. Quelqu'un enquête sur la même chose que moi.", quando = "noite", fase = "jovem" },
                { "J'ai été témoin d'un crime : quelqu'un a corné une page et a fait comme si de rien n'était. Je l'ai vu. Je vois toujours tout.", fase = "jovem" },
                { "J'ai changé de peau et laissé l'ancienne dans le coin. Voilà une pièce à conviction contre moi, en pleine lumière. Détective amatrice.", quando = "muda", fase = "jovem" },
                { "Les détectives des livres vieillissent avec charme. Moi, j'ai vieilli avec l'humidité.", fase = "adulta" },
                { "D'abord, j'écarte l'évidence. Puis j'écarte le chat. Ce qui reste, si improbable soit-il, c'est le balai.", fase = "adulta", curta = "Le chat écarté, reste le balai." },
                { "Je cherche le mobile de celui qui me poursuit. Je ne le trouve pas. C'est le crime le plus effrayant : celui qui n'a pas besoin de mobile.", fase = "adulta" },
                { "J'avoue : j'ai mangé la page des remerciements. C'était la plus sucrée du livre. Je ne regrette pas, je constate.", fase = "adulta" },
                { "Être l'éternelle suspecte a un avantage : personne ne cherche le vrai coupable.", fase = "adulta" },
                { "J'ai laissé une fausse piste au ménage : une miette près de la fenêtre. Pendant qu'ils regardaient là-bas, je changeais de livre.", fase = "adulta" },
                { "Il y a une vieille affaire jamais résolue dans cette maison : la disparition de l'encyclopédie, tome F. Je sais. Je ne dis rien.", fase = "adulta" },
                { "Il y a des crimes que personne ne résoudra, et mon frère en a été un.", quando = "triste", fase = "adulta" },
                { "J'ai résolu trop d'affaires pour croire aux coïncidences. Dans cette maison, rien ne tombe tout seul de l'étagère.", fase = "ancia" },
                { "Avant de partir, je veux résoudre le mystère du salon : qui pose toujours sa tasse sur le livre.", fase = "ancia" },
                { "Je garde en mémoire toutes les affaires de cette maison : chaque ménage, chaque bombe d'insecticide, chaque livre disparu. Je suis l'archive vivante.", fase = "ancia" },
                { "Conseil de vétérane : qui nettoie trop cache quelque chose.", fase = "ancia", curta = "Qui nettoie trop cache quelque chose." },
                { "Un jour, on découvrira que je n'étais pas coupable de tout. Seulement de presque tout.", fase = "ancia" },
                { "Au petit matin, la maison avoue des choses : le tuyau qui grince, le bois qui craque, le souffle de qui lit.", quando = "noite", fase = "ancia" },
                { "Je me méfie de mes souvenirs : ils me donnent toujours le beau rôle.", fase = "ancia" },
                { "Chaque matin, la maison se réveille pleine de preuves : vaisselle dans l'évier, chausson dans le couloir, livre ouvert sur le canapé." },
                { "Je me méfie de {personagem} depuis la première page. Je n'ai pas de preuves. J'ai de l'instinct et de la faim, qui tombent souvent juste." },
                { "{personagem} a un alibi trop parfait. Les alibis trop parfaits sont ceux qui tiennent le plus longtemps, jusqu'à la dernière page." },
                { "{personagem} pose les bonnes questions. Je pose les mêmes, mais au mur." },
                { "Chaque fois que {personagem} entre en scène, la page devient plus silencieuse. Il y a des gens qui ont un secret en poche." },
                { "Je traite « {livro} » comme un dossier : chaque page une preuve, chaque chapitre un interrogatoire. J'ai déjà mangé trois dépositions." },
                { "Les bons livres cachent la réponse là où tout le monde regarde. C'est pour ça que je mange « {livro} » par les bords." },
                { "J'ai trouvé « {livro} » ouvert par terre, dos en l'air. Négligence, précipitation, ou le chat. J'enquête." },
                { "Je soupçonne {autor} d'avoir connu la fin dès la première ligne. Les coupables aussi la connaissent toujours." },
                { "{autor} sème les indices comme on sème des miettes : exprès, pour voir qui suit." },
                { "Il y a eu {evento}. Tout le monde va faire attention à ça. Moi, je vais faire attention à qui n'a pas réagi." },
                { "Dans tout bon polar, {evento} sert à cacher autre chose. Je vais chercher l'autre chose." },
                { "Après « {anterior} », j'ai appris à ne me fier à personne avant le dernier chapitre. Pas même à moi." },
                { "Ma vie, vue de loin, ressemble à {lente} : beaucoup d'indices, aucune preuve, et quelqu'un qui porte toujours des gants." },
                { "Le mot « {palavra} » réapparaît. Une fois, c'est le hasard ; deux fois, une coïncidence ; trois fois, un indice." },
                { "Ce livre parle {de_tema} avec le calme de quelqu'un qui cache quelque chose. Les coupables aussi parlent calmement." },
                { "Tu tournes la page plus lentement quand la tension monte. Je l'ai remarqué. Les détectives remarquent." },
                { "Tu lis en cachette de qui ? Je ne dirai rien. Je note." },
                { "Tout duo de détectives a quelqu'un qui lit et quelqu'un qui mange les preuves. Tu sais déjà qui fait quoi." },
                { "Ventre vide, flair aiguisé. D'ici, je sens l'odeur d'un biscuit oublié derrière le canapé.", quando = "fome" },
                { "Ventre plein. Affaire classée. Les détectives fument une fois tout résolu ; moi, je m'allonge sur le dos d'un livre.", quando = "cheia" },
                { "La meilleure heure pour un crime, c'est le petit matin. Je le sais : c'est l'heure où je mange.", quando = "noite" },
                { "Triste parce que j'ai découvert la vérité et que je n'ai personne à qui la dire. C'est la punition des petits témoins.", quando = "triste" },
                { "Chaque ménage est une descente de police. Ils retournent tout et repartent sans personne." },
                { "J'ai un dossier de trois pages contre le chat. Personne ne le lit. Les puissants s'en sortent toujours." },
                { "La naphtaline, c'est du poison qui sent la grand-mère. Le genre de crime que personne n'appelle un crime.", curta = "Naphtaline : du poison qui sent la mamie." },
                { "J'en ai déduit que quelqu'un a changé ce livre de place. La poussière l'a dit. La poussière parle toujours." },
                { "J'ai découvert qu'un livre de cette étagère cache de l'argent. Je ne dirai pas lequel. Les mites aussi ont une éthique." },
            },
            lentes = { "une scène de crime", "un interrogatoire sans avocat", "une affaire classée trop tôt" },
            fechos = { "C'est noté.", "Le coupable revient toujours à l'étagère.", "Personne ne quitte cette maison sans s'expliquer." },
        },
        -- 3. horreur et gothique : la maison qui respire, ce qui habite les murs ; elle est le monstre et elle a peur
        horror = {
            frases = {
                { "Pour les humains, le monstre de cette maison, c'est moi : petite, argentée, sortant des fentes la nuit. Ils ne se méfient jamais de ce qui habite les murs avec moi.", curta = "Le monstre de la maison, c'est moi. Et les murs ?" },
                { "La nuit, le papier humide craque lentement, comme un os qui ne veut pas casser d'un coup. Je reste éveillée pour voir qui abandonnera le premier.", quando = "noite" },
                { "Il y a une odeur nouvelle dans « {livro} » : vieux moisi mêlé de main nerveuse. Soit le livre pourrit, soit quelqu'un l'a lu en ayant peur." },
                { "J'ai trouvé la mue d'une vieille mite entre les pages de « {livro} », entière, comme si elle était repartie à pied. Je n'ai pas cherché le reste. Certaines questions vous mangent en retour." },
                { "Après {evento}, la page devient plus froide. Je le sens par les pattes. Les humains le sentent dans la nuque et appellent ça du suspense." },
                { "Chaque fois que {personagem} entre dans la page, je recule de deux paragraphes. Je ne sais pas pourquoi. Mon corps le sait et ne me le dit pas.", fase = { "ninfa", "jovem" }, curta = "{personagem} arrive. Mon corps a reculé tout seul." },
                { "J'ai entendu un bruit dans le placard et je me suis cachée dans une virgule. J'y suis encore. La virgule tremble aussi.", fase = "ninfa" },
                { "Je suis descendue à la cave pleine de courage. Je suis remontée sans courage, avec une antenne de dignité en moins. La cave est toujours là, bouche ouverte.", fase = "jovem" },
                { "Ce livre a une odeur {de_tema} du début à la fin. À mon âge, je le sais : ce qu'un livre sent trop fort, c'est ce qu'il a peur de dire.", fase = "adulta" },
                { "Cette maison durera plus longtemps que moi, et elle le sait. Parfois les planches grincent comme quelqu'un qui rit tout bas.", fase = "ancia" },
                { "En pleine nuit, l'étagère ressemble à {lente}. Au matin, elle redevient une étagère. Je ne me fie pas à ce qui change de visage comme ça." },
                { "Le pire, dans le noir, ce n'est pas quand il bouge. C'est quand il se tient tranquille et qu'il attend.", fase = { "adulta", "ancia" }, curta = "Noir immobile, noir qui attend." },
                { "Ceux qui écrivent sur les fantômes n'ont jamais habité un mur. Moi si, et je te le garantis : ce qui fait peur, ce n'est pas le bruit, c'est le silence juste après.", fase = { "adulta", "ancia" } },
                { "Je ne sais pas encore ce qu'est le noir, mais lui sait déjà qui je suis.", fase = "ninfa" },
                { "On m'a raconté qu'il existe un livre qui mange les mites. On a ri. Après, plus personne n'a voulu dormir dans l'encyclopédie.", fase = "ninfa" },
                { "J'ai collé mon antenne au mur et j'ai entendu un cœur. C'était le mien. Mais pendant une seconde, non.", fase = "ninfa", curta = "Un cœur dans le mur. Le mien. Presque." },
                { "J'ai regardé par la fente de la porte, et quelque chose m'a regardée en retour. C'était le chat. Je suis presque sûre que c'était le chat.", fase = "ninfa" },
                { "J'ai découvert que je suis ce dont les humains ont peur. J'ai eu peur de moi, et je ne sais pas où fuir.", fase = "ninfa" },
                { "Seule dans un dos de livre pour la première fois. J'ai compté les pages pour m'endormir. Arrivée à mille deux, la page mille deux a chuchoté.", fase = "ninfa" },
                { "La cave a des livres que personne n'a lus depuis trente ans. Ils ne dorment pas. Ils attendent.", fase = "jovem", curta = "Les livres de la cave ne dorment pas. Ils attendent." },
                { "Il y a un miroir au bout du couloir. Personne ne passe devant la nuit. Même pas les humains. Je le remarque.", fase = "jovem" },
                { "Il y a un livre enfermé dans un tiroir. Parfois, j'entends ses pages tourner. Personne n'a la clé. Personne ne se souvient de l'avoir enfermé.", fase = "jovem" },
                { "J'ai été courageuse toute la journée. La nuit, j'ai payé l'addition.", fase = "jovem" },
                { "Il y a une tache au plafond qui change de forme. Lundi, c'était un visage. Mardi, une main. Aujourd'hui, je n'ai pas regardé.", fase = "jovem" },
                { "Trois heures du matin : l'heure où même l'horloge se tait. Je me tais aussi, pour ne pas être la seule à faire du bruit.", quando = "noite", fase = "jovem" },
                { "Les tuyaux de cette maison chuchotent des noms. L'un d'eux ressemblait au mien. J'ai changé de livre.", fase = "jovem" },
                { "Personne ne parle du pire de la mue : laisser derrière soi une version vide de soi, encore debout.", quando = "muda", fase = "jovem" },
                { "J'ai accepté d'être le monstre de la maison. Au moins, les monstres n'ont pas à demander la permission d'entrer.", fase = "adulta" },
                { "J'ai appris à vivre avec ce qui habite le faux plafond. Je ne demande pas son nom. Les noms appellent les choses.", fase = "adulta" },
                { "Le moisi ne crie pas, ne mord pas, ne poursuit pas. Il reste, c'est tout. Le pire genre de monstre.", fase = "adulta", curta = "Le moisi ne crie ni ne poursuit. Il reste." },
                { "Je retrouve de vieilles sœurs pressées dans les livres comme des fleurs séchées. Les humains disent que c'est dégoûtant. Moi, je dis que c'est un cimetière.", fase = "adulta" },
                { "L'insecticide sent la lavande, maintenant. C'est l'horreur moderne : la mort parfumée.", fase = "adulta" },
                { "Les vieilles maisons ne sont pas hantées. On s'en souvient trop, c'est tout.", fase = "adulta" },
                { "Dans mon cauchemar, les pages sont blanches. Personne n'a rien écrit. Rien à manger, rien à craindre. C'est le pire.", fase = "adulta" },
                { "Aujourd'hui je n'ai pas peur ; je suis fatiguée d'avoir peur. C'est plus sombre.", quando = "triste", fase = "adulta" },
                { "À mon âge, les bruits de la maison sont de vieilles connaissances. Je ne m'effraie plus que des silences que je ne connais pas.", fase = "ancia" },
                { "La mort habite trois étagères plus bas. Parfois, elle monte faire la conversation. Je n'ai pas encore accepté l'invitation.", fase = "ancia" },
                { "Les planches grincent comme quelqu'un qui rit de nous tout bas. Elles ont leurs raisons.", fase = "ancia" },
                { "Je suis devenue une histoire pour faire peur aux nymphes. Je n'ai rien fait. J'ai juste trop duré.", fase = "ancia" },
                { "Vieille, je dors peu. Je passe la nuit à écouter la maison, comme on écoute respirer un malade.", quando = "noite", fase = "ancia" },
                { "Conseil de vieille : si une page est froide, ne la mange pas. Certaines faims n'en valent pas la peine.", fase = "ancia" },
                { "Je croyais que la vieillesse ôtait la peur. Elle ôte juste la hâte de fuir.", fase = "ancia" },
                { "Toute vieille maison a un poumon. Celui de celle-ci est derrière la bibliothèque, et j'habite dedans." },
                { "{personagem} ne devrait pas ouvrir cette porte. Je le dis toujours aux personnages. Aucun ne m'écoute.", curta = "{personagem}, n'ouvre pas cette porte." },
                { "Quand {personagem} parle bas, le papier se refroidit. Je l'ai remarqué deux fois. À la troisième, je change de chapitre." },
                { "Je ne me fie pas à {personagem}. Il y a des gens qui entrent dans une page comme dans une cave : sans allumer." },
                { "Je soutiens {personagem} comme on soutient quelqu'un dans un livre d'horreur : en sachant que ça ne sert à rien." },
                { "Je jure que « {livro} » devient plus lourd la nuit. Le jour, il pèse son poids normal. Le jour, il fait semblant." },
                { "« {livro} » sent la cave et la bougie éteinte. Je le mange quand même. La peur, ça creuse." },
                { "« {livro} » a une page cornée que je n'ai jamais cornée. Personne ici ne l'a cornée. Elle reste cornée." },
                { "{autor} sait des choses que personne ne devrait savoir. Ça se sent au goût de la page : amer, froid, ancien." },
                { "{autor} m'a appris que le pire monstre est celui que personne ne décrit. Depuis, je regarde surtout ce qui manque." },
                { "Après {evento}, la page s'est refroidie. Je le sens par les pattes. Quelque chose est sorti de l'histoire et resté dans le salon." },
                { "Il y a eu {evento} dans la page, et le chat n'a plus miaulé de la nuit. Les chats savent avant nous." },
                { "Certaines lectures ne s'en vont pas quand on ferme le livre. « {anterior} » s'est installé sous ma plinthe." },
                { "L'étagère, aujourd'hui, ressemblait à {lente}. J'ai compté les livres deux fois. Au deuxième compte, il y en avait un de plus." },
                { "Je n'ai pas voulu manger « {palavra} ». Il y a des mots qu'on avale et qui continuent de parler à l'intérieur." },
                { "Ce livre parle {de_tema} comme on chuchote dans la chambre d'à côté. Je reste l'antenne collée au mur, à écouter." },
                { "Tu lis en pleine nuit à la lumière de la lampe. Depuis la plinthe, ton ombre sur le mur est immense. Parfois, tu me fais peur." },
                { "Quand tu t'arrêtes de lire d'un coup, je m'arrête aussi. On écoute la même chose." },
                { "S'il te plaît, n'éteins pas au milieu du chapitre. J'en suis encore au passage de la cave.", curta = "N'éteins pas. J'en suis au passage de la cave." },
                { "La faim au petit matin, c'est une faim avec des dents. Elle sort de l'estomac et se promène dans la maison.", quando = "fome" },
                { "J'ai mangé un chapitre sombre et maintenant je suis pleine d'ombre. Lourde, silencieuse, la lumière éteinte à l'intérieur.", quando = "cheia" },
                { "Des pas dans le faux plafond. Légers, réguliers, sans hâte. Pas le chat : les chats ne montent pas si haut. Pas un rat : les rats ont peur.", quando = "noite" },
                { "Il y a une tristesse qui habite les vieilles maisons. Aujourd'hui, elle est venue s'asseoir à côté de moi.", quando = "triste" },
                { "Le balai n'a pas de visage, pas de voix, pas de hâte. Il revient, c'est tout, chaque semaine, comme un fantôme ponctuel." },
                { "Le chat fixe le coin vide du salon. Je le fixe aussi. Aucun de nous ne cligne des yeux.", curta = "Le chat fixe le coin vide. Moi aussi." },
                { "Ce livre sent la peau qu'on a mise de côté. Je ne sais pas de qui." },
                { "Le pire, ce n'est pas le craquement de l'étagère. C'est le long silence d'après, quand la maison attend de voir si quelqu'un s'est réveillé." },
                { "Pour eux, je suis le frisson de trouver quelque chose de vivant dans un livre. Pour moi, ils sont le frisson de trouver une main." },
            },
            lentes = { "une maison qui respire", "une cave sans issue", "une chambre que personne n'ouvre" },
            fechos = { "Et la maison a tout entendu.", "Ne regarde pas derrière l'étagère.", "Quelque chose est resté dans le noir." },
        },
    },
}
